# try mean reversion vs momentum depending on horizon
# Previous sim showed thr8 with lag10 fwd50 net positive 1.06 vs full spread, but sim with realistic 1 lot/step gave -158 still negative
# Maybe we need to consider inventory holding more efficiently: target 1 means 10 lots, flipping costs many trades
# Let's try signal with smaller target size to reduce slippage: e.g., target 0.2 = 2 lots
def sim2(thr, lag, lot_size):
    N=len(mid)
    target=np.zeros(N)
    for t in range(lag,N):
        if np.isfinite(mid[t]) and np.isfinite(mid[t-lag]):
            past_v = mid[t]-mid[t-lag]
            if abs(past_v)>thr:
                # scale target proportional to past?
                target[t]=np.sign(past_v)*lot_size
            else:
                target[t]=0
    target_lots=target*10
    cash=0
    inv=0
    for t in range(N):
        tl=target_lots[t]
        if inv < tl-1e-9:
            inv = min(inv+1, tl)
            cash -= ask[t] if np.isfinite(ask[t]) else mid[t]
        elif inv > tl+1e-9:
            inv = max(inv-1, tl)
            cash += bid[t] if np.isfinite(bid[t]) else mid[t]
    final=cash+inv*mid[N-1] if np.isfinite(mid[N-1]) else cash
    return float(final)

