def corr(x, y):
    m = np.isfinite(x) & np.isfinite(y)
    x = x[m]
    y = y[m]
    if len(x) < 100:
        return float('nan')
    xc = x - np.mean(x)
    yc = y - np.mean(y)
    return float(np.sum(xc*yc) / np.sqrt(np.sum(xc*xc)*np.sum(yc*yc)+1e-12))
