def signal(obs):
    a='A'
    # retrieve histories
    mid = obs.hist(a, 'mid', 260)
    imb = obs.hist(a, 'imbalance', 60)
    # need enough data, else keep previous
    if len(mid) < 210 or len(imb) < 15:
        prev = obs.state.get('prev_target', -0.4)
        return {a: float(prev)}
    # check finite
    if not np.isfinite(mid[-1]) or not np.isfinite(imb[-1]):
        prev = obs.state.get('prev_target', -0.4)
        return {a: float(prev)}

    # --- features ---
    # past10 return
    if np.isfinite(mid[-1]) and np.isfinite(mid[-11]):
        past10 = float(mid[-1] - mid[-11])
    else:
        past10 = 0.0

    # imbalance MA10
    w = imb[-10:]
    fin = w[np.isfinite(w)]
    if len(fin) >= 6:
        imb_ma10 = float(np.mean(fin))
    elif len(fin) > 0:
        imb_ma10 = float(np.mean(fin))
    else:
        imb_ma10 = 0.0

    # long drift 200 steps
    if np.isfinite(mid[-1]) and np.isfinite(mid[-201]):
        drift200 = float(mid[-1] - mid[-201])
    else:
        # fallback 50
        drift200 = float(mid[-1] - mid[-51]) * 4.0 if np.isfinite(mid[-51]) else 0.0

    # predictive component (regression betas ~ 0.19* past10 +2.0*imb -0.36 for h10)
    pred = 0.19 * past10 + 1.9 * imb_ma10 - 0.36

    # drift component scaled, tanh gives [-1,1]
    # drift200 mean ~ -8, std ~12, scale 15
    drift_sig = math.tanh(drift200 / 15.0)

    # predictive signal scaled
    pred_sig = math.tanh(pred / 1.2)

    # combine: 65% drift, 35% pred
    raw = 0.65 * drift_sig + 0.35 * pred_sig

    # EMA smoothing to cut turnover
    prev_ema = obs.state.get('ema_raw', raw)
    alpha = 0.12
    ema = alpha * raw + (1 - alpha) * prev_ema
    obs.state['ema_raw'] = ema

    # hysteresis / deadband and rate limit
    prev_target = obs.state.get('prev_target', -0.4)
    # deadband 0.12
    if abs(ema - prev_target) < 0.12:
        target = prev_target
    else:
        delta = ema - prev_target
        # limit step to 0.18 per call (every 10 steps => ~0.018 per step)
        if delta > 0:
            if delta > 0.18:
                delta = 0.18
        else:
            if delta < -0.18:
                delta = -0.18
        target = prev_target + delta
        # clip
        if target > 1.0:
            target = 1.0
        if target < -1.0:
            target = -1.0
        obs.state['prev_target'] = target

    # final clip
    if target > 1.0:
        target = 1.0
    if target < -1.0:
        target = -1.0
    obs.state['prev_target'] = target
    return {a: float(target)}

