mid = H['A']['mid']
n = len(mid)
def fwd_corr(lag, fwd):
    # past lag return vs forward fwd return
    past = mid[lag: n-fwd] - mid[:n-fwd-lag]
    fwdR = mid[lag+fwd: n] - mid[lag: n-fwd]
    # mask nan
    m = np.isfinite(past) & np.isfinite(fwdR)
    past = past[m]; fwdR = fwdR[m]
    if len(past) < 100:
        return float('nan')
    c = np.corrcoef(past, fwdR)[0,1]
    return float(c)

