    a='A'
    mid = obs.hist(a, 'mid', 260)
    imb = obs.hist(a, 'imbalance', 60)
    if len(mid) < 210 or len(imb) < 15:
        prev = obs.state.get('prev_target', -0.4)
        return {a: float(prev)}
    if not np.isfinite(mid[-1]) or not np.isfinite(imb[-1]):
        prev = obs.state.get('prev_target', -0.4)
        return {a: float(prev)}
    if np.isfinite(mid[-1]) and np.isfinite(mid[-11]):
        past10 = float(mid[-1] - mid[-11])
    else:
        past10 = 0.0
    w = imb[-10:]
    fin = w[np.isfinite(w)]
    if len(fin) >= 6:
        imb_ma10 = float(np.mean(fin))
    elif len(fin) > 0:
        imb_ma10 = float(np.mean(fin))
    else:
        imb_ma10 = 0.0
    if np.isfinite(mid[-1]) and np.isfinite(mid[-201]):
        drift200 = float(mid[-1] - mid[-201])
    else:
        drift200 = float(mid[-1] - mid[-51]) * 4.0 if np.isfinite(mid[-51]) else 0.0
    pred = 0.19 * past10 + 1.9 * imb_ma10 - 0.36
    drift_sig = math.tanh(drift200 / 15.0)
    pred_sig = math.tanh(pred / 1.2)
    raw = 0.65 * drift_sig + 0.35 * pred_sig
    prev_ema = obs.state.get('ema_raw', raw)
    alpha = 0.12
    ema = alpha * raw + (1 - alpha) * prev_ema
    obs.state['ema_raw'] = ema
    prev_target = obs.state.get('prev_target', -0.4)
