def ma(arr,w):
    out=np.full(len(arr), np.nan)
    filled=np.where(np.isfinite(arr), arr, 0)
    mask=np.isfinite(arr).astype(float)
    cumsum=np.cumsum(filled)
    cumcnt=np.cumsum(mask)
    for t in range(len(arr)):
        s=max(0,t-w+1)
        tot=cumsum[t] - (cumsum[s-1] if s>0 else 0)
        cnt=cumcnt[t] - (cumcnt[s-1] if s>0 else 0)
        if cnt >= w*0.6:
            out[t]=tot/cnt
    return out
