    if len(mid) < 12 or len(imb) < 10:
        prev = obs.state.get('prev_target', 0.0)
        return {a: float(prev)}
    if not np.isfinite(mid[-1]):
        prev = obs.state.get('prev_target', 0.0)
        return {a: float(prev)}
    # past 10-step return (momentum)
    if np.isfinite(mid[-1]) and np.isfinite(mid[-11]):
        past10 = float(mid[-1] - mid[-11])
    else:
        past10 = 0.0
    # imbalance MA10 (most robust predictor, corr ~0.19 fwd10, ~0.24 fwd20 overall, ~0.36 recent)
    w = imb[-10:]
    fin = w[np.isfinite(w)]
    if len(fin) >= 5:
        imb_ma = float(np.mean(fin))
    else:
        # fallback to shorter window
        w2 = imb[-5:]
        fin2 = w2[np.isfinite(w2)]
        if len(fin2) > 0:
            imb_ma = float(np.mean(fin2))
        else:
            imb_ma = 0.0
    # predictive score: compromise between overall beta (0.23*past+3.35*imb) and recent regime (0.11*past+7.3*imb)
    # overweight imbalance which is stable across epochs, underweight past which is unstable
