        drift200 = float(mid[-1] - mid[-201])
    elif np.isfinite(mid[-51]):
        drift200 = float(mid[-1] - mid[-51]) * 4.0
    else:
        drift200 = 0.0

    # deadzone threshold to avoid churn on small drifts
    thr = 12.0
    if abs(drift200) < thr:
        raw = 0.0
    else:
        # scale drift to [-1,1] via tanh, scale ~20
        raw = math.tanh(drift200 / 20.0)

    # EMA with very low alpha to enforce low turnover (update effectively ~ every 100 steps)
    prev_ema = obs.state.get('ema_raw', raw)
    alpha = 0.08
    ema = alpha * raw + (1 - alpha) * prev_ema
    obs.state['ema_raw'] = ema

    prev_target = obs.state.get('prev_target', 0.0)
    # counter to limit updates to every ~50-100 steps (called every 10 steps)
    cnt = obs.state.get('cnt', 0) + 1
    obs.state['cnt'] = cnt

    # only allow target change every 5 calls (~50 steps) unless large move
    # hysteresis 0.2 and rate limit 0.15
    if abs(ema - prev_target) < 0.22:
        target = prev_target
    else:
        # enforce infrequent updates: skip if not 5th call and change not huge
        if cnt % 5 != 0 and abs(ema - prev_target) < 0.35:
            target = prev_target
        else:
            delta = ema - prev_target
            if delta > 0.15:
                delta = 0.15
            if delta < -0.15:
                delta = -0.15
            target = prev_target + delta
            if target > 1.0:
                target = 1.0
            if target < -1.0:
                target = -1.0
            obs.state['prev_target'] = target
            return {a: float(target)}

    if target > 1.0:
        target = 1.0
    if target < -1.0:
        target = -1.0
    obs.state['prev_target'] = target
    return {a: float(target)}

